-- 107_verified_management_outputs.sql
-- Roadmap J.59-J.62: deterministic management outputs from sealed structured data.
BEGIN;
CREATE OR REPLACE FUNCTION public.get_verified_management_outputs(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$DECLARE u uuid:=auth.uid();h public.historical_project_records%ROWTYPE;i jsonb;tender jsonb;budget jsonb;narrative jsonb;recommendations jsonb:='[]'::jsonb;BEGIN IF u IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'MANAGEMENT_OUTPUTS_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT*INTO h FROM public.historical_project_records WHERE project_id=p_project_id;IF h.id IS NULL THEN RAISE EXCEPTION'MANAGEMENT_OUTPUTS_REQUIRE_SEALED_PROJECT'USING ERRCODE='55000';END IF;i:=public.get_historical_project_intelligence(p_project_id);
tender:=jsonb_build_object('title','Tender Commercial Summary','contractor',h.payload#>>'{contractorScorecard,contractor_name}','awardValue',h.payload#>'{cost,award_value}','currencyCode',h.payload#>>'{cost,currency_code}','finalApprovedVariations',h.payload#>'{variations,final_approved_variation_value}','finalCost',h.payload#>'{cost,final_cost}','varianceToAward',h.payload#>'{cost,variance_to_award}','commercialOutcome',CASE WHEN(h.payload#>>'{cost,variance_to_award}')::numeric<=0 THEN'AT_OR_BELOW_AWARD'ELSE'ABOVE_AWARD'END);
budget:=jsonb_build_object('title','Budget Management Summary','approvedBudget',h.payload#>'{cost,approved_budget}','awardValue',h.payload#>'{cost,award_value}','latestForecast',h.payload#>'{cost,latest_forecast}','finalCost',h.payload#>'{cost,final_cost}','varianceToBudget',h.payload#>'{cost,variance_to_budget}','budgetAccuracyScore',i->'budgetAccuracyScore','forecastAccuracyScore',i->'forecastAccuracyScore');
narrative:=jsonb_build_object('title','Forecast and Closeout Narrative','statements',jsonb_build_array('Final cost: '||(h.payload#>>'{cost,final_cost}')||' '||(h.payload#>>'{cost,currency_code}'),'Completion variance: '||(h.payload#>>'{schedule,completion_variance_days}')||' days','Snags at handover: '||(h.payload#>>'{quality,open_at_handover}'),'Approved variations: '||(h.payload#>>'{variations,approved_count}')||', rejected: '||(h.payload#>>'{variations,rejected_count}'),'Outstanding certified payments: '||(h.payload#>>'{payments,outstanding_value}')||' '||(h.payload#>>'{payments,currency_code}')),'sourceRecordId',h.id,'sourceHash',h.payload_hash);
IF(h.payload#>>'{cost,variance_to_budget}')::numeric>0 THEN recommendations:=recommendations||jsonb_build_array(jsonb_build_object('priority','HIGH','area','BUDGET','recommendation','Apply the historical award-to-final factor during future budget approval.','evidence',i#>'{futureBudgetIntelligence,recommendedAwardToFinalFactor}'));END IF;IF(h.payload#>>'{schedule,completion_variance_days}')::integer>0 THEN recommendations:=recommendations||jsonb_build_array(jsonb_build_object('priority','HIGH','area','SCHEDULE','recommendation','Use recorded delay drivers and recovery actions when approving the next baseline.','evidence',h.payload#>'{schedule,delay_drivers}'));END IF;IF(h.payload#>>'{quality,open_at_handover}')::integer>0 THEN recommendations:=recommendations||jsonb_build_array(jsonb_build_object('priority','MEDIUM','area','QUALITY','recommendation','Introduce earlier Work Group snag closure gates before handover.','evidence',h.payload#>'{quality,snags_by_work_group}'));END IF;IF(h.payload#>>'{variations,pending_count}')::integer>0 THEN recommendations:=recommendations||jsonb_build_array(jsonb_build_object('priority','HIGH','area','COMMERCIAL','recommendation','Do not seal future projects with unresolved variation exposure.','evidence',h.payload#>'{variations,pending_count}'));END IF;IF jsonb_array_length(recommendations)=0 THEN recommendations:=jsonb_build_array(jsonb_build_object('priority','LOW','area','CONTINUOUS_IMPROVEMENT','recommendation','Reuse the confirmed lessons learned and contractor scorecard on the next comparable project.','evidence',h.payload#>'{lessons,change_next_time}'));END IF;
RETURN jsonb_build_object('projectId',p_project_id,'verifiedSource',jsonb_build_object('recordId',h.id,'payloadHash',h.payload_hash,'sealedAt',h.sealed_at),'tenderCommercialSummary',tender,'budgetManagementSummary',budget,'forecastCloseoutNarrative',narrative,'managementRecommendations',recommendations,'generationMethod','DETERMINISTIC_STRUCTURED_DATA_RULES');END;$$;REVOKE ALL ON FUNCTION public.get_verified_management_outputs(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.get_verified_management_outputs(bigint)TO authenticated;COMMIT;
